    if (!window.confirm("¿Seguro que deseas eliminar esta planilla?")) return;
    try {
      const res = await fetch(`${API_URL}/planilla/${id}`, { method: "DELETE" });
      if (res.ok) {
        setPlanillas(planillas.filter(p => p.id !== id));
        alert("Planilla eliminada exitosamente");
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo eliminar la planilla"}`);
